const r = await tools.exec_command({"cmd":"python3 - <<'PY'
from pathlib import Path
import h5py,numpy as np,re,collections

def chars(x): return ''.join(chr(int(c)) for c in np.asarray(x).ravel(order='F') if c)
def val(f,x):
 if isinstance(x,h5py.Reference): x=f[x]
 if isinstance(x,h5py.Dataset):
  a=x[()]
  if x.attrs.get('MATLAB_class',b'')==b'char': return chars(a)
  return np.asarray(a).squeeze()
 return x

def refs_values(f,ds): return [val(f,r) for r in ds[()].ravel(order='F')]

def probe_locs(f,nprobes):
 for prefix in ['obj/meta/probe','obj/ex/probe']:
  if prefix+'/loc' in f:
   ds=f[prefix+'/loc']
   if ds.dtype==object: return [str(v) for v in refs_values(f,ds)]
   return [str(val(f,ds))]
 return ['unknown']*nprobes

roots=['Ephys_Behavior','RandomizedDelay_Ephys_Behavior']
for root in roots:
 rows=[]
 for p in sorted(Path(root).glob('data_structure_*.mat')):
  m=re.match(r'data_structure_(.+)_(\d{4}-\d{2}-\d{2})',p.stem); animal,date=m.groups()
  with h5py.File(p,'r') as f:
   ntr=int(np.asarray(f['obj/bp/Ntrials'])[0,0])
   clu_refs=f['obj/clu'][()].ravel(order='F'); nprobes=len(clu_refs)
   locs=probe_locs(f,nprobes)
   probes=[]
   for i,r in enumerate(clu_refs):
    g=f[r]; qualities=[str(v).strip() for v in refs_values(f,g['quality'])]
    elig=sum(q.lower() not in {'garbage','gabrga','noisy','real?'} for q in qualities)
    probes.append((len(qualities),elig,collections.Counter(q.lower() for q in qualities)))
   def arr(k): return np.asarray(f['obj/bp/'+k]).ravel().astype(float)
   bp={k:arr(k) for k in ['hit','miss','no','early','autowater','R','L']}
   stim=np.asarray(f['obj/bp/stim/enable']).ravel().astype(float)
   gocue=np.asarray(f['obj/bp/ev/goCue']).ravel().astype(float)
   traj_refs=f['obj/traj'][()].ravel(order='F')
   traj=[]
   for r in traj_refs:
    g=f[r]
    n=len(g['ts'])
    dropped=[]
    for v in refs_values(f,g['NdroppedFrames']):
     try: dropped.append(float(np.asarray(v).squeeze()))
     except: dropped.append(np.nan)
    traj.append((n,int(np.sum(np.isfinite(dropped)))))
   rows.append(dict(file=p.name,animal=animal,date=date,ntr=ntr,nprobes=nprobes,locs=locs,probes=probes,
                    hit=int(bp['hit'].sum()),miss=int(bp['miss'].sum()),no=int(bp['no'].sum()),early=int(bp['early'].sum()),
                    wc=int(bp['autowater'].sum()),stim=int(stim.sum()),gocue_nan=int(np.isnan(gocue).sum()),traj=traj))
 print('\nROOT',root,'files',len(rows),'subjects',sorted(set(x['animal'] for x in rows)))
 print('trials',sum(x['ntr'] for x in rows),'raw clusters all probes',sum(sum(p[0] for p in x['probes']) for x in rows),'quality eligible',sum(sum(p[1] for p in x['probes']) for x in rows))
 print('outcome hit/miss/no',sum(x['hit'] for x in rows),sum(x['miss'] for x in rows),sum(x['no'] for x in rows),'WC',sum(x['wc'] for x in rows),'stim',sum(x['stim'] for x in rows),'early',sum(x['early'] for x in rows))
 print('sessions by subject',dict(collections.Counter(x['animal'] for x in rows)))
 for x in rows:
  print(x['file'], 'tr',x['ntr'],'loc',x['locs'],'clu',[(p[0],p[1]) for p in x['probes']], 'H/M/N',x['hit'],x['miss'],x['no'],'WC',x['wc'],'stim',x['stim'],'early',x['early'],'gcnan',x['gocue_nan'],'traj',x['traj'])
PY","workdir":"/app/data","yield_time_ms":30000,"max_output_tokens":50000});
text(r.output);

