from pathlib import Path
from scipy.io import loadmat
import h5py,numpy as np,re,collections,gc

def chars(x): return ''.join(chr(int(c)) for c in np.asarray(x).ravel(order='F') if c)
def hval(f,x):
 if isinstance(x,h5py.Reference): x=f[x]
 if isinstance(x,h5py.Dataset):
  a=x[()]
  if x.attrs.get('MATLAB_class',b'')==b'char': return chars(a)
  return np.asarray(a).squeeze()
 return x
def refs_values(f,ds): return [hval(f,r) for r in ds[()].ravel(order='F')]
def hscan(p):
 with h5py.File(p,'r') as f:
  bp=f['obj/bp']; ntr=int(np.asarray(bp['Ntrials']).squeeze())
  refs=f['obj/clu'][()].ravel(order='F') if 'obj/clu' in f else []
  probes=[]
  for r in refs:
   g=f[r]
   if not isinstance(g,h5py.Group): probes.append([]); continue
   probes.append([str(x).strip() for x in refs_values(f,g['quality'])])
  loc=[]
  for pref in ['obj/meta/probe','obj/ex/probe']:
   if pref+'/loc' in f:
    ds=f[pref+'/loc']; loc=[str(x) for x in refs_values(f,ds)] if ds.dtype==object else [str(hval(f,ds))]; break
  def a(q): return np.asarray(f['obj/bp/'+q]).ravel().astype(float)
  return ntr,probes,loc,{q:int(np.nansum(a(q))) for q in ['hit','miss','no','early','autowater']},int(np.nansum(a('stim/enable')))
def getfield(s,name): return getattr(s,name)
def charish(x):
 x=np.asarray(x).squeeze()
 if x.dtype.kind in 'US': return str(x.item() if x.shape==() else ''.join(x.ravel()))
 if x.dtype==object:
  try: return charish(x.item())
  except: return str(x)
 return str(x)
def vscan(p):
 o=loadmat(p,struct_as_record=False,squeeze_me=False,variable_names=['obj'])['obj'][0,0]
 bp=o.bp[0,0]; ntr=int(np.asarray(bp.Ntrials).squeeze()); probes=[]
 if hasattr(o,'clu'):
  for cell in o.clu.ravel(order='F'):
   if not isinstance(cell,np.ndarray) or cell.size==0: probes.append([]); continue
   qs=[]
   for c in cell.ravel(order='F'):
    q=getattr(c,'quality',''); qs.append(charish(q).strip())
   probes.append(qs)
 loc=[]
 ex=getattr(o,'ex',None)
 try:
  ex=ex[0,0]; pr=ex.probe
  for pp in pr.ravel(order='F'):
   try: loc.append(charish(pp.loc))
   except: pass
 except: pass
 def a(name):
  cur=bp
  for part in name.split('/'): cur=getattr(cur,part); cur=cur[0,0] if isinstance(cur,np.ndarray) and cur.shape==(1,1) and cur.dtype==object else cur
  return np.asarray(cur).ravel().astype(float)
 out=ntr,probes,loc,{q:int(np.nansum(a(q))) for q in ['hit','miss','no','early','autowater']},int(np.nansum(a('stim/enable')))
 del o; gc.collect(); return out
rows=[]
for p in sorted(Path('RandomizedDelay_Ephys_Behavior').glob('data_structure_*.mat')):
 animal,date=re.match(r'data_structure_(.+)_(\d{4}-\d{2}-\d{2})',p.stem).groups()
 try: vals=hscan(p)
 except OSError: vals=vscan(p)
 ntr,probes,loc,bp,stim=vals
 eligible=[sum(q.lower() not in {'garbage','gabrga','noisy','real?'} for q in qs) for qs in probes]
 rows.append((p.name,animal,ntr,[len(q) for q in probes],eligible,loc,bp,stim))
 print(p.name,'tr',ntr,'clu',[len(q) for q in probes],'elig',eligible,'loc',loc,'bp',bp,'stim',stim,flush=True)
print('\nTOTAL sessions',len(rows),'neural_sessions',sum(bool(sum(r[3])) for r in rows),'subjects',sorted(set(r[1] for r in rows)))
print('trials all',sum(r[2] for r in rows),'trials neural',sum(r[2] for r in rows if sum(r[3])))
print('clusters',sum(sum(r[3]) for r in rows),'eligible',sum(sum(r[4]) for r in rows))
for k in ['hit','miss','no','early','autowater']: print(k,sum(r[6][k] for r in rows))
print('stim',sum(r[7] for r in rows))
