function [obj,cluid] = removeLowFRClusters(obj,cluid,lowFR,prbnum)
% % Remove low-firing rate units, e.g., all those firing less than lowFR
%   spikes per second on average across all trials.
%   
%   The fitted observation noise (diagonal element of R) for a
%   low-firing rate unit will be small, so the neural trajectory may
%   show a deflection each time the neuron spikes.

meanFRs = mean(mean(obj.psth{prbnum},3,'omitnan'),'omitnan');
use = meanFRs > lowFR;

% remove low fr clusters
cluid = cluid(use);
obj.psth{prbnum} = obj.psth{prbnum}(:,use,:);
obj.trialdat{prbnum} = obj.trialdat{prbnum}(:,use,:);

end % removeLowFRClustersfunction [xvel, yvel] = findVelocity(xpos, ypos, feat)


for i = 1:size(xpos,2) % for each trial
    tsinterp = [xpos(:,i) ypos(:,i)];
    basederiv = median(diff(tsinterp),'omitnan');

    % find the difference between the feat velocity and the
    % baseline feature velocity (NOT FOR TONGUE)
    xvel(:,i) = gradient(tsinterp(:,1));
    yvel(:,i) = gradient(tsinterp(:,2));
    if ~contains(feat,'tongue') %|| strcmp(traj(trix).featNames{feat},'nose')
        xvel(:,i) = xvel(:,i) - basederiv(1);
        yvel(:,i) = yvel(:,i) - basederiv(1);
    end

    % fill missing values for all features
    if ~contains(feat,'tongue')
        xvel(:,i) = fillmissing(xvel(:,i),'nearest');
        yvel(:,i) = fillmissing(yvel(:,i),'nearest');
    else
        tempx = xvel(:,i);
        tempx(isnan(tempx)) = 0; % set tongue velocity to 0 if not visible
        xvel(:,i) = tempx;
        tempy = yvel(:,i);
        tempy(isnan(tempy)) = 0; % set tonge velocity to 0 if not visible
        yvel(:,i) = tempy;
    end
end


end  % findVelocity





function me = loadMotionEnergy(obj,meta,params,datapth,varargin)

if nargin > 4
    returnAfterLoad = varargin{1};
else
    returnAfterLoad = 0;
end

% %------------------------------------------------------------
% % --first check to see if obj has an 'me' and has thresh--
